CREATE OR REPLACE FUNCTION notify_{{table_name}}_change() RETURNS trigger AS $$
BEGIN
  PERFORM pg_notify('{{channel_name}}', json_build_object('op', TG_OP, 'id', NEW.id)::text);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER {{table_name}}_notify
AFTER INSERT OR UPDATE ON {{table_name}}
FOR EACH ROW EXECUTE FUNCTION notify_{{table_name}}_change();
